SELECT 
  FROM sys90_after_service a
       INNER JOIN sys01_company b ON a.sys90_company_id = b.sys01_company_id
 WHERE f_trunc(a.sys90_happen_date) BETWEEN #{p.happenStartDate} AND #{p.happenEndDate}
   AND b.sys01_company_nm LIKE #{p.companyText}
   AND COALESCE(a.sys90_state_cd, ' ') LIKE #{p.stateCd}
   AND COALESCE(a.sys90_type_yn, ' ') LIKE #{p.typeYn}
   AND COALESCE(a.sys90_confirm_yn, 'false') LIKE #{p.confirmYn}
   AND UPPER(CONCAT(a.sys90_happen_reason, a.sys90_reg_emp_nm, a.sys90_worker, a.sys90_remarks)) LIKE UPPER(#{p.searchText})
 ORDER BY a.sys90_happen_date DESC

SELECT 
  FROM sys90_after_service a
       INNER JOIN sys01_company b ON a.sys90_company_id = b.sys01_company_id
 WHERE f_trunc(a.sys90_happen_date) BETWEEN #{p.happenStartDate} AND #{p.happenEndDate}
   AND b.sys01_company_nm LIKE #{p.companyText}
   AND COALESCE(a.sys90_state_cd, ' ') NOT IN ('10', '90')
   AND COALESCE(a.sys90_type_yn, ' ') LIKE #{p.typeYn}
   AND COALESCE(a.sys90_confirm_yn, 'false') LIKE #{p.confirmYn}
   AND UPPER(CONCAT(a.sys90_happen_reason, a.sys90_reg_emp_nm, a.sys90_worker, a.sys90_remarks)) LIKE UPPER(#{p.searchText})
 ORDER BY a.sys90_happen_date DESC

