UPDATE sys90_after_service
   SET sys90_worker = #{r.worker}
     , sys90_due_date = #{r.dueDate}
     , sys90_state_cd = #{r.stateCd}
     , sys90_happen_remedy = #{r.happenRemedy}
     , sys90_remarks = #{r.remarks}
 WHERE sys90_after_service_id = #{r.afterServiceId}

UPDATE sys90_after_service
   SET sys90_remarks = #{remarks}
 WHERE sys90_after_service_id = #{afterServiceId}
